document.querySelector('#view3dBtn').onclick=()=>set3DView(!view3d);
function geometryFor(name){const T=THREE3D;switch(name){case'Sphere':return new T.SphereGeometry(.9,40,28);case'Capsule':return new T.CapsuleGeometry(.52,.75,8,20);case'Torus':case'Donut':return new T.TorusGeometry(.68,.26,18,48);case'Cone':return new T.ConeGeometry(.85,1.8,40);case'Pyramid':return new T.ConeGeometry(1,1.8,4);case'Cylinder':return new T.CylinderGeometry(.72,.72,1.5,40);default:return new T.BoxGeometry(1.5,1.5,1.5)}}
