function updateSceneCount(){const n=meshList.length;document.querySelector('#sceneCount').textContent=n+' object'+(n===1?'':'s');if(view3d)document.querySelector('#statusRight').textContent=n+' 3D object'+(n===1?'':'s')}
function selectMesh(mesh){if(selectionBox){scene3d.remove(selectionBox);selectionBox.geometry.dispose();selectionBox.material.dispose();selectionBox=null}selectedMesh=mesh;if(transformControls3d){if(mesh&&showInteractionControls)transformControls3d.attach(mesh);else transformControls3d.detach()}if(mesh){selectionBox=new THREE3D.BoxHelper(mesh,0x0878b9);scene3d.add(selectionBox)}}
function on3DSelect(e){if(!THREE3D||e.button!==0)return;const rect=renderer3d.domElement.getBoundingClientRect(),mouse=new THREE3D.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),ray=new THREE3D.Raycaster();ray.setFromCamera(mouse,camera3d);const hits=ray.intersectObjects(meshList,true);const hit=hits[0]?.object||null,root=hit?meshList.find(r=>r===hit||r.getObjectById(hit.id)):null;selectMesh(root||null)}
function dispose3DTree(root){root.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>{for(const v of Object.values(m))if(v?.isTexture)v.dispose();m.dispose()})}})}function removeLast3DObject(){if(!meshList.length){toast('The scene is empty');return}const mesh=selectedMesh||meshList.at(-1);scene3d.remove(mesh);dispose3DTree(mesh);meshList=meshList.filter(m=>m!==mesh);selectMesh(null);updateSceneCount();toast(mesh.name+' removed')}
document.addEventListener('keydown',e=>{if(view3d&&(e.key==='Delete'||e.key==='Backspace')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();removeLast3DObject()}});

