let selectionObj=null,selectionDrag=null,fileOpenMode='open';
const welcomeScreen=document.querySelector('#welcomeScreen'),fileMenu=document.querySelector('#fileMenu'),saveDialog=document.querySelector('#saveDialog'),fileContent=document.querySelector('#fileContent');
const welcomePreference=localStorage.getItem('paint3d.showWelcome');document.querySelector('#skipWelcome').checked=welcomePreference!=='false';welcomeScreen.hidden=welcomePreference==='false';
document.querySelector('#skipWelcome').onchange=e=>localStorage.setItem('paint3d.showWelcome',String(e.target.checked));
function setCanvasTool(tool){set3DView(false);state.tab='brushes';document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab==='brushes'));document.querySelectorAll('#selectBtn,#cropBtn,#magicBtn').forEach(b=>b.classList.remove('tool-active'));state.tool=tool;const buttons={select:'#selectBtn',crop:'#cropBtn',magic:'#magicBtn'};if(buttons[tool])document.querySelector(buttons[tool]).classList.add('tool-active');renderPanel();toast(({select:'Drag on canvas to select artwork',crop:'Drag an area to crop',magic:'Click a flat-color area to select it'})[tool])}
function selectionCanvasPoint(p){const s=selectionObj,cx=s.x+s.w/2,cy=s.y+s.h/2,dx=p.x-cx,dy=p.y-cy,a=-(s.angle||0);return{x:dx*Math.cos(a)-dy*Math.sin(a)+s.w/2,y:dx*Math.sin(a)+dy*Math.cos(a)+s.h/2}}
function paintSelection(){pctx.clearRect(0,0,preview.width,preview.height);if(!selectionObj)return;const s=selectionObj,cx=s.x+s.w/2,cy=s.y+s.h/2;pctx.save();pctx.translate(cx,cy);pctx.rotate(s.angle||0);pctx.drawImage(s.image,-s.w/2,-s.h/2,s.w,s.h);pctx.setLineDash([6,4]);pctx.lineWidth=1.5;pctx.strokeStyle='#fff';pctx.strokeRect(-s.w/2-.5,-s.h/2-.5,s.w+1,s.h+1);pctx.setLineDash([3,4]);pctx.strokeStyle='#25334d';pctx.strokeRect(-s.w/2-.5,-s.h/2-.5,s.w+1,s.h+1);pctx.setLineDash([]);const pts=[[-s.w/2,-s.h/2],[0,-s.h/2],[s.w/2,-s.h/2],[s.w/2,0],[s.w/2,s.h/2],[0,s.h/2],[-s.w/2,s.h/2],[-s.w/2,0]];for(const [x,y] of pts){pctx.fillStyle='#fff';pctx.strokeStyle='#25334d';pctx.lineWidth=1.2;pctx.fillRect(x-5,y-5,10,10);pctx.strokeRect(x-5,y-5,10,10)}if(state.tool!=='crop'){pctx.beginPath();pctx.moveTo(0,-s.h/2);pctx.lineTo(0,-s.h/2-24);pctx.strokeStyle='#25334d';pctx.stroke();pctx.beginPath();pctx.arc(0,-s.h/2-31,8,0,Math.PI*2);pctx.fillStyle='#fff';pctx.fill();pctx.stroke()}pctx.restore()}
