function startMarquee(p){commitSelection();saveHistory();selectionDrag={kind:'marquee',start:p};state.drawing=true;pctx.clearRect(0,0,preview.width,preview.height)}
function makeSelection(a,b){const x=Math.max(0,Math.floor(Math.min(a.x,b.x))),y=Math.max(0,Math.floor(Math.min(a.y,b.y))),right=Math.min(canvas.width,Math.ceil(Math.max(a.x,b.x))),bottom=Math.min(canvas.height,Math.ceil(Math.max(a.y,b.y))),w=right-x,h=bottom-y;if(w<3||h<3){pctx.clearRect(0,0,preview.width,preview.height);return}const temp=document.createElement('canvas');temp.width=w;temp.height=h;temp.getContext('2d').putImageData(ctx.getImageData(x,y,w,h),0,0);ctx.clearRect(x,y,w,h);selectionObj={x,y,w,h,image:temp,angle:0};document.querySelector('#make3dBtn').hidden=false;paintSelection();refreshCanvasTexture()}
function selectionPointerDown(e,p){wrap.setPointerCapture(e.pointerId);state.drawing=true;if(state.tool==='magic'){magicSelect(p);state.drawing=false;return}if(selectionObj){const s=selectionObj,loc=selectionCanvasPoint(p),rotY=-31;if(state.tool!=='crop'&&Math.abs(loc.x-s.w/2)<13&&Math.abs(loc.y-rotY)<14){const cx=s.x+s.w/2,cy=s.y+s.h/2;selectionDrag={kind:'rotate',center:{x:cx,y:cy},startAngle:Math.atan2(p.y-cy,p.x-cx),angle:s.angle||0};return}const l=Math.abs(loc.x)<10,r=Math.abs(loc.x-s.w)<10,t=Math.abs(loc.y)<10,b=Math.abs(loc.y-s.h)<10;if((l||r||t||b)&&loc.x>=-12&&loc.x<=s.w+12&&loc.y>=-12&&loc.y<=s.h+12){selectionDrag={kind:'resize',edgeX:l?-1:r?1:0,edgeY:t?-1:b?1:0,start:p,rect:{x:s.x,y:s.y,w:s.w,h:s.h}};return}if(loc.x>=0&&loc.x<=s.w&&loc.y>=0&&loc.y<=s.h){selectionDrag={kind:'move',start:p,origin:{x:s.x,y:s.y}};return}commitSelection()}startMarquee(p)}
function selectionPointerMove(e){let p=point(e);const d=selectionDrag;if(!d)return;if(d.kind==='marquee'){if(state.tool==='crop')p=constrainCrop(d.start,p);pctx.clearRect(0,0,preview.width,preview.height);const x=Math.min(d.start.x,p.x),y=Math.min(d.start.y,p.y),w=Math.abs(p.x-d.start.x),h=Math.abs(p.y-d.start.y);pctx.setLineDash([7,5]);pctx.strokeStyle='#fff';pctx.lineWidth=3;pctx.strokeRect(x,y,w,h);pctx.strokeStyle='#273450';pctx.lineWidth=1;pctx.strokeRect(x,y,w,h);pctx.setLineDash([]);return}const s=selectionObj;if(d.kind==='move'){s.x=d.origin.x+p.x-d.start.x;s.y=d.origin.y+p.y-d.start.y}else if(d.kind==='rotate'){s.angle=d.angle+Math.atan2(p.y-d.center.y,p.x-d.center.x)-d.startAngle}else if(d.kind==='resize'){s.angle=0;const r=d.rect;let l=r.x,t=r.y,rr=r.x+r.w,bb=r.y+r.h;if(d.edgeX<0)l=Math.min(p.x,rr-2);if(d.edgeX>0)rr=Math.max(p.x,l+2);if(d.edgeY<0)t=Math.min(p.y,bb-2);if(d.edgeY>0)bb=Math.max(p.y,t+2);s.x=l;s.y=t;s.w=rr-l;s.h=bb-t}paintSelection()}
