function cropSelection(){if(!selectionObj)return;const s=selectionObj,w=Math.max(1,Math.round(s.w)),h=Math.max(1,Math.round(s.h)),img=document.createElement('canvas');img.width=w;img.height=h;img.getContext('2d').drawImage(s.image,0,0,w,h);selectionObj=null;document.querySelector('#make3dBtn').hidden=true;pctx.clearRect(0,0,preview.width,preview.height);canvas.width=preview.width=w;canvas.height=preview.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0);wrap.style.aspectRatio=w+'/'+h;document.querySelector('#statusLeft').textContent=w+' × '+h+' px';resizeCanvasPlane();refreshCanvasTexture();toast('Canvas cropped')}
function magicSelect(p){commitSelection();const sx=Math.max(0,Math.min(canvas.width-1,Math.floor(p.x))),sy=Math.max(0,Math.min(canvas.height-1,Math.floor(p.y))),w=canvas.width,h=canvas.height,img=ctx.getImageData(0,0,w,h),data=img.data,n=w*h,seed=(sy*w+sx)*4;if(data[seed+3]===0)return toast('Nothing to select here');saveHistory();const target=[data[seed],data[seed+1],data[seed+2]],seen=new Uint8Array(n),queue=new Int32Array(n);let head=0,tail=0,minX=w,minY=h,maxX=-1,maxY=-1;const matches=i=>{const k=i*4,dr=data[k]-target[0],dg=data[k+1]-target[1],db=data[k+2]-target[2];return data[k+3]>0&&dr*dr+dg*dg+db*db<1800};const first=sy*w+sx;seen[first]=1;queue[tail++]=first;while(head<tail){const i=queue[head++],x=i%w,y=(i-x)/w,k=i*4;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);if(x>0){const j=i-1;if(!seen[j]&&matches(j)){seen[j]=1;queue[tail++]=j}}if(x<w-1){const j=i+1;if(!seen[j]&&matches(j)){seen[j]=1;queue[tail++]=j}}if(y>0){const j=i-w;if(!seen[j]&&matches(j)){seen[j]=1;queue[tail++]=j}}if(y<h-1){const j=i+w;if(!seen[j]&&matches(j)){seen[j]=1;queue[tail++]=j}}}const sw=maxX-minX+1,sh=maxY-minY+1,selected=document.createElement('canvas');selected.width=sw;selected.height=sh;const sctx=selected.getContext('2d'),out=sctx.createImageData(sw,sh);for(let q=0;q<tail;q++){const i=queue[q],x=i%w,y=(i-x)/w,src=i*4,dst=((y-minY)*sw+x-minX)*4;out.data[dst]=data[src];out.data[dst+1]=data[src+1];out.data[dst+2]=data[src+2];out.data[dst+3]=data[src+3];data[src+3]=0}ctx.putImageData(img,0,0);sctx.putImageData(out,0,0);selectionObj={x:minX,y:minY,w:sw,h:sh,image:selected,angle:0};document.querySelector('#make3dBtn').hidden=false;refreshCanvasTexture();state.tool='select';document.querySelector('#magicBtn').classList.remove('tool-active');document.querySelector('#selectBtn').classList.add('tool-active');paintSelection();toast('Color region selected · drag to move')}
