function fileBase(){return (document.querySelector('#docTitle').textContent.trim().split(' - ')[0]||'Untitled').replace(/[^a-z0-9_-]+/gi,'-')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function savePNG(){commitSelection();downloadBlob(dataURLBlob(canvas.toDataURL('image/png')),fileBase()+'.png');toast('PNG saved')}
function dataURLBlob(url){const [head,body]=url.split(',');const mime=head.match(/:(.*?);/)[1],raw=atob(body),arr=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);return new Blob([arr],{type:mime})}
function clone3DForExport(){const group=new THREE3D.Group();for(const root of meshList){const clone=root.clone(true);clone.traverse(o=>{if(o.isMesh){o.geometry=o.geometry.clone();if(Array.isArray(o.material))o.material=o.material.map(m=>m.clone());else if(o.material)o.material=o.material.clone()}});group.add(clone)}return group}
async function exportSceneBinary(){if(!THREE3D)throw new Error('3D engine is not initialized');const {GLTFExporter}=await import('three/addons/exporters/GLTFExporter.js');const exporter=new GLTFExporter();return new Promise((resolve,reject)=>exporter.parse(clone3DForExport(),resolve,reject,{binary:true}))}
function projectDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('paint3d-projects',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('projects'))req.result.createObjectStore('projects',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function projectStore(mode,value){const db=await projectDB();return new Promise((resolve,reject)=>{const tx=db.transaction('projects',mode),store=tx.objectStore('projects');let req;if(mode==='readonly')req=value==='all'?store.getAll():store.get(value);else req=store.put(value);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();tx.onerror=()=>reject(tx.error)})}
async function saveProject(){commitSelection();try{const sceneGlb=meshList.length?arrayBufferToBase64(await exportSceneBinary()):null;const project={format:'paint3d',version:2,width:canvas.width,height:canvas.height,image:canvas.toDataURL('image/png'),sceneGlb};const record={id:crypto.randomUUID?.()||('project-'+Date.now()),title:fileBase(),updatedAt:Date.now(),project};await projectStore('readwrite',record);state.projectId=record.id;toast('Openable project saved · find it in Open')}catch(err){console.error(err);toast('Could not save this project')}}
async function renderSavedProjects(){const host=fileContent.querySelector('#savedProjects');if(!host)return;try{const rows=await projectStore('readonly','all');host.replaceChildren();if(!rows.length){host.textContent='No saved projects yet.';return}rows.sort((a,b)=>b.updatedAt-a.updatedAt).forEach(row=>{const button=document.createElement('button');button.className='saved-project';button.type='button';button.innerHTML='<span class="saved-project-icon">'+icon('shapes')+'</span><span class="saved-project-name"></span><span class="saved-project-date"></span>';button.querySelector('.saved-project-name').textContent=row.title||'Untitled';button.querySelector('.saved-project-date').textContent=new Date(row.updatedAt).toLocaleDateString();button.onclick=()=>{state.projectId=row.id;fileMenu.hidden=true;welcomeScreen.hidden=true;loadProject(row.project,(row.title||'Untitled')+'.paint3d')};host.append(button)});lucide.createIcons()}catch(err){console.error(err);host.textContent='Saved projects are unavailable in this browser.'}}
async function saveGLB(){if(!meshList.length)return toast('Add or import a 3D model before saving');try{const result=await exportSceneBinary();downloadBlob(new Blob([result],{type:'model/gltf-binary'}),fileBase()+'.glb');toast('3D model exported as GLB')}catch(err){console.error(err);toast('3D model export failed')}}
function arrayBufferToBase64(input){const bytes=input instanceof Uint8Array?input:new Uint8Array(input);let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
function base64ToArrayBuffer(str){const binary=atob(str),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes.buffer}
function openSaveDialog(){saveDialog.hidden=false}
document.querySelector('#closeSave').onclick=()=>saveDialog.hidden=true;saveDialog.addEventListener('click',e=>{if(e.target===saveDialog)saveDialog.hidden=true});saveDialog.querySelectorAll('[data-saveformat]').forEach(b=>b.onclick=()=>{saveDialog.hidden=true;if(b.dataset.saveformat==='png')savePNG();else if(b.dataset.saveformat==='glb')saveGLB();else saveProject()});
function newDocument(){commitSelection();canvas.width=preview.width=1280;canvas.height=preview.height=720;wrap.style.aspectRatio='1280/720';updateZoomLayout();document.querySelector('#statusLeft').textContent='1280 × 720 px';ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);refreshCanvasTexture();resizeCanvasPlane();state.history=[];state.redo=[];saveHistory();if(scene3d){for(const mesh of meshList){scene3d.remove(mesh);dispose3DTree(mesh)}meshList=[];canvasPlane=null;canvasPlaneTexture=null;canvasPlaneVisible=false;selectMesh(null);updateSceneCount()}document.querySelector('#docTitle').textContent='Untitled - Paint 3D';state.projectId=null;state.tool='brush';state.cropRatio=null;document.querySelectorAll('#selectBtn,#cropBtn,#magicBtn').forEach(b=>b.classList.remove('tool-active'));document.querySelector('#make3dBtn').hidden=true;welcomeScreen.hidden=true;fileMenu.hidden=true;set3DView(false);toast('New canvas ready')}
function browseFile(mode){fileOpenMode=mode;fileMenu.hidden=true;document.querySelector('#fileInput').value='';document.querySelector('#fileInput').click()}
function renderFilePage(page){document.querySelectorAll('.file-item').forEach(b=>b.classList.toggle('selected',b.dataset.file===page));if(page==='open')fileContent.innerHTML='<h1>Open</h1><button class="browse-button" id="browseFiles">Browse files</button><p class="file-message">Open an image, Paint 3D project, or GLB model.</p><h2 class="saved-heading">Saved projects</h2><div id="savedProjects" class="saved-project-list"></div>';else if(page==='new')fileContent.innerHTML='<h1>New</h1><p>Start with a fresh blank canvas.</p><button class="panel-btn primary" id="newFromMenu">'+icon('file-plus-2')+' New canvas</button>';else if(page==='insert')fileContent.innerHTML='<h1>Insert</h1><button class="browse-button" id="browseFiles">Browse files</button><p class="file-message">Place an image on the current canvas.</p>';else if(page==='save')fileContent.innerHTML='<h1>Save</h1><p>Save your current artwork as a PNG image.</p><button class="panel-btn primary" id="savePNGMenu">'+icon('image')+' Save image</button>';else if(page==='saveas')fileContent.innerHTML='<h1>Save as copy</h1><p>Choose an image, editable project, or 3D model format.</p><button class="panel-btn primary" id="saveAsMenu">Choose a format…</button>';else if(page==='print')fileContent.innerHTML='<h1>Print</h1><p>Print the current 2D canvas.</p><button class="panel-btn primary" id="printNow">Print</button>';else if(page==='settings')fileContent.innerHTML='<h1>Settings</h1><label class="check-row"><input type="checkbox" id="welcomeSetting" '+(localStorage.getItem('paint3d.showWelcome')!=='false'?'checked':'')+'> Show welcome screen on launch</label><p class="file-message">Your preference is saved on this device.</p>';else if(page==='share')fileContent.innerHTML='<h1>Share</h1><p>Share this Paint 3D canvas with a link.</p><button class="panel-btn primary" id="shareLink">'+icon('share-2')+' Share</button>';else if(page==='mixed')fileContent.innerHTML='<h1>Mixed reality</h1><p>Export a 3D model to use it in other 3D apps.</p><button class="panel-btn primary" id="export3d">'+icon('box')+' Save 3D model</button>';else fileContent.innerHTML='<h1>Learn and Feedback</h1><p>Use the 3D shapes tab to build a scene, or draw on the 2D canvas with brushes and shapes.</p>';
lucide.createIcons();const browse=fileContent.querySelector('#browseFiles');if(browse)browse.onclick=()=>browseFile(page==='insert'?'insert':'open');const newBtn=fileContent.querySelector('#newFromMenu');if(newBtn)newBtn.onclick=newDocument;const save=fileContent.querySelector('#savePNGMenu');if(save)save.onclick=savePNG;const saveas=fileContent.querySelector('#saveAsMenu');if(saveas)saveas.onclick=openSaveDialog;const print=fileContent.querySelector('#printNow');if(print)print.onclick=()=>window.print();const setting=fileContent.querySelector('#welcomeSetting');if(setting)setting.onchange=()=>{localStorage.setItem('paint3d.showWelcome',String(setting.checked));document.querySelector('#skipWelcome').checked=setting.checked};const share=fileContent.querySelector('#shareLink');if(share)share.onclick=()=>shareProjectLink();const exp=fileContent.querySelector('#export3d');if(exp)exp.onclick=saveGLB;if(page==='open')renderSavedProjects()}
function showFileMenu(page='open'){fileMenu.hidden=false;renderFilePage(page)}
document.querySelector('#menuBtn').onclick=()=>showFileMenu('open');document.querySelector('#fileBack').onclick=()=>fileMenu.hidden=true;document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{const page=b.dataset.file;if(page==='new'){renderFilePage('new');return}if(page==='open'||page==='insert'){renderFilePage(page);return}if(page==='save'){fileMenu.hidden=true;commitSelection();savePNG();return}if(page==='saveas'){renderFilePage(page);return}if(page==='settings'||page==='share'||page==='mixed'||page==='print'||page==='help'){renderFilePage(page);return}});
document.querySelector('#welcomeNew').onclick=newDocument;document.querySelector('#welcomeOpen').onclick=()=>{welcomeScreen.hidden=true;showFileMenu('open')};
async function shareProjectLink(){const url=location.href;if(navigator.share){try{await navigator.share({title:'Paint 3D',text:'Open my Paint 3D canvas',url})}catch{}}else if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('Link copied')}else toast('Copy this page URL to share')}
async function handleFile(file){if(!file)return;fileMenu.hidden=true;welcomeScreen.hidden=true;const mode=fileOpenMode;if(/\.glb$/i.test(file.name)||file.type==='model/gltf-binary'){await importGLBFile(file,mode==='open');return}if(/\.(paint3d|json)$/i.test(file.name)||file.type==='application/json'){try{const project=JSON.parse(await file.text());if(project.format!=='paint3d')throw new Error('Not a Paint 3D project');loadProject(project,file.name)}catch(err){console.error(err);toast('Could not open this project file')}return}if(!file.type.startsWith('image/'))return toast('Choose an image or .paint3d project');const img=new Image();img.onload=()=>{if(mode==='open'){saveHistory();ctx.clearRect(0,0,canvas.width,canvas.height)}else{commitSelection();saveHistory()}const scale=Math.min(canvas.width/img.width,canvas.height/img.height,mode==='insert'?.55:1);ctx.drawImage(img,(canvas.width-img.width*scale)/2,(canvas.height-img.height*scale)/2,img.width*scale,img.height*scale);refreshCanvasTexture();URL.revokeObjectURL(img.src);toast(mode==='insert'?'Image inserted':'Image opened')};img.onerror=()=>toast('Could not open this image');img.src=URL.createObjectURL(file)}
async function loadProject(project,fileName){if(!project.image)return toast('This project has no canvas image');const image=new Image();image.onload=async()=>{canvas.width=preview.width=project.width||image.width;canvas.height=preview.height=project.height||image.height;wrap.style.aspectRatio=canvas.width+'/'+canvas.height;updateZoomLayout();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);document.querySelector('#statusLeft').textContent=canvas.width+' × '+canvas.height+' px';resizeCanvasPlane();refreshCanvasTexture();if(project.sceneGlb){const ok=await init3D();if(ok){for(const root of meshList){scene3d.remove(root);dispose3DTree(root)}meshList=[];canvasPlane=null;canvasPlaneTexture=null;canvasPlaneVisible=false;try{await parseGLBBuffer(base64ToArrayBuffer(project.sceneGlb),'Project scene',false);set3DView(true)}catch(err){console.error(err);toast('3D scene could not be restored')}}}else if(project.objects?.length){const ok=await init3D();if(ok){for(const root of meshList){scene3d.remove(root);dispose3DTree(root)}meshList=[];canvasPlane=null;canvasPlaneTexture=null;canvasPlaneVisible=false;for(const item of project.objects){const mesh=new THREE3D.Mesh(geometryFor(item.name),new THREE3D.MeshStandardMaterial({color:item.color||'#4b76e8',roughness:.42}));mesh.name=item.name;mesh.position.fromArray(item.position||[0,.9,0]);mesh.rotation.fromArray(item.rotation||[0,0,0]);mesh.scale.fromArray(item.scale||[1,1,1]);mesh.castShadow=true;mesh.receiveShadow=true;scene3d.add(mesh);meshList.push(mesh)}updateSceneCount();set3DView(true)}}document.querySelector('#docTitle').textContent=(fileName?fileName.replace(/\.(paint3d|json)$/i,''):fileBase())+' - Paint 3D';saveHistory();toast('Project opened')};image.src=project.image}

function updateCustomCropRatio(){const w=Number(inspector.querySelector('#cropW')?.value||state.cropW||640),h=Number(inspector.querySelector('#cropH')?.value||state.cropH||360);if(w>0&&h>0){state.cropW=w;state.cropH=h;state.cropRatio=w/h}}
function constrainCrop(start,end){let ratio=state.cropRatio;if(ratio==='custom')ratio=(state.cropW||640)/(state.cropH||360);if(!ratio)return end;let dx=end.x-start.x,dy=end.y-start.y,sx=Math.sign(dx)||1,sy=Math.sign(dy)||1,w=Math.abs(dx),h=Math.abs(dy);if(!w&&!h)return end;if(w/Math.max(h,.01)>ratio)h=w/ratio;else w=h*ratio;return{x:start.x+sx*w,y:start.y+sy*h}}
async function parseGLBBuffer(buffer,name='Imported GLB',normalize=true){const ok=await init3D();if(!ok)throw new Error('3D is unavailable');const {GLTFLoader}=await import('three/addons/loaders/GLTFLoader.js');const loader=new GLTFLoader();return new Promise((resolve,reject)=>loader.parse(buffer,'',gltf=>{const root=gltf.scene||gltf.scenes[0];addModelRoot(root,name,normalize);resolve(root)},reject))}
function addModelRoot(root,name,normalize=true){root.name=name;root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});root.updateMatrixWorld(true);if(normalize){const box=new THREE3D.Box3().setFromObject(root);if(!box.isEmpty()){const size=box.getSize(new THREE3D.Vector3()),center=box.getCenter(new THREE3D.Vector3()),fit=3/Math.max(size.x,size.y,size.z,0.001);root.scale.multiplyScalar(fit);root.position.addScaledVector(center,-fit);root.position.y+=(-box.min.y)*fit}}scene3d.add(root);meshList.push(root);selectMesh(root);updateSceneCount();return root}
async function importGLBFile(file,replace=false){try{if(!file.name.toLowerCase().endsWith('.glb')&&file.type!=='model/gltf-binary'){toast('Choose a .glb model file');return}const ok=await init3D();if(!ok)return;if(replace){for(const root of meshList){scene3d.remove(root);dispose3DTree(root)}meshList=[];canvasPlane=null;canvasPlaneTexture=null;canvasPlaneVisible=false;selectMesh(null)}set3DView(true);const url=URL.createObjectURL(file),{GLTFLoader}=await import('three/addons/loaders/GLTFLoader.js');new GLTFLoader().load(url,gltf=>{URL.revokeObjectURL(url);addModelRoot(gltf.scene,file.name.replace(/\.glb$/i,''),true);toast('GLB model imported')},undefined,err=>{URL.revokeObjectURL(url);console.error(err);toast('Could not load this GLB model')})}catch(err){console.error(err);toast('GLB support could not initialize')}}
function refreshCanvasTexture(){if(canvasPlaneTexture)canvasPlaneTexture.needsUpdate=true}function resizeCanvasPlane(){if(!canvasPlane||!THREE3D)return;canvasPlane.geometry.dispose();canvasPlane.geometry=new THREE3D.PlaneGeometry(5,5*canvas.height/canvas.width);refreshCanvasTexture()}
function toggleCanvasPlane(enabled){canvasPlaneVisible=enabled;if(!THREE3D){init3D().then(ok=>{if(ok)toggleCanvasPlane(enabled)});return}if(enabled){set3DView(true);if(!canvasPlane){canvasPlaneTexture=new THREE3D.CanvasTexture(canvas);canvasPlaneTexture.colorSpace=THREE3D.SRGBColorSpace;const mat=new THREE3D.MeshStandardMaterial({map:canvasPlaneTexture,side:THREE3D.DoubleSide,roughness:.9,transparent:state.transparent});canvasPlane=new THREE3D.Mesh(new THREE3D.PlaneGeometry(5,5*canvas.height/canvas.width),mat);canvasPlane.name='Canvas plane';canvasPlane.position.set(0,2.5,-2);canvasPlane.castShadow=true;canvasPlane.receiveShadow=true}if(!meshList.includes(canvasPlane)){scene3d.add(canvasPlane);meshList.push(canvasPlane)}}else if(canvasPlane&&meshList.includes(canvasPlane)){scene3d.remove(canvasPlane);meshList=meshList.filter(m=>m!==canvasPlane);if(selectedMesh===canvasPlane)selectMesh(null)}updateSceneCount()}
function addArtwork3D(){init3D().then(ok=>{if(!ok)return;const src=selectionObj?.image||canvas,w=selectionObj?.w||canvas.width,h=selectionObj?.h||canvas.height,texture=new THREE3D.CanvasTexture(src);texture.colorSpace=THREE3D.SRGBColorSpace;const width=4.2,height=width*h/w,mat=new THREE3D.MeshStandardMaterial({map:texture,transparent:true,side:THREE3D.DoubleSide,roughness:state.material==='Glossy'?.18:.72,metalness:state.material==='Metallic'?.65:.02,opacity:state.opacity});const mesh=new THREE3D.Mesh(new THREE3D.PlaneGeometry(width,height),mat);mesh.name='Artwork plane';mesh.position.set(0,1.4,0);mesh.castShadow=true;mesh.receiveShadow=true;scene3d.add(mesh);meshList.push(mesh);set3DView(true);selectMesh(mesh);updateSceneCount();toast('2D artwork added as a 3D plane')})}
function setInteractionControls(enabled){showInteractionControls=enabled;if(transformControls3d){if(enabled&&selectedMesh)transformControls3d.attach(selectedMesh);else transformControls3d.detach()}const controlItem=quickMenu.querySelector('[data-quick="controls"]');if(controlItem)controlItem.innerHTML=icon('move-3d')+(enabled?' Hide interaction controls':' Show interaction controls');lucide.createIcons();toast(enabled?'3D interaction handles on':'3D interaction handles off')}
function reset3DView(){if(!camera3d||!controls3d){setZoom(100);return}camera3d.position.set(6,5.5,8);controls3d.target.set(0,.6,0);controls3d.update();toast('3D view reset')}
async function pasteFromClipboard(){try{if(!navigator.clipboard?.read)throw new Error('Clipboard image read unavailable');const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(t=>t.startsWith('image/'));if(type){const blob=await item.getType(type);fileOpenMode='insert';handleFile(new File([blob],'clipboard.png',{type}));return}}toast('No image found in clipboard')}catch(err){toast('Clipboard paste is not available here')}}
async function takeWorkspaceScreenshot(){if(view3d&&renderer3d){renderer3d.render(scene3d,camera3d);renderer3d.domElement.toBlob(blob=>blob&&downloadBlob(blob,fileBase()+'-3d.png'))}else savePNG()}
document.querySelector('#make3dBtn').onclick=addArtwork3D;
document.querySelector('#pasteBtn').onclick=pasteFromClipboard;document.querySelector('#historyBtn').onclick=()=>toast('Use Undo and Redo to browse recent edits');document.querySelector('#ribbonCollapse').onclick=()=>{document.querySelector('.app-shell').classList.toggle('ribbon-collapsed');document.querySelector('#ribbonCollapse').title=document.querySelector('.app-shell').classList.contains('ribbon-collapsed')?'Expand ribbon':'Collapse ribbon'};
const moreButton=document.querySelector('#moreBtn'),quickMenu=document.querySelector('#quickMenu');quickMenu.querySelector('[data-quick="controls"]').innerHTML=icon('move-3d')+(showInteractionControls?' Hide interaction controls':' Show interaction controls');lucide.createIcons();moreButton.onclick=()=>quickMenu.hidden=!quickMenu.hidden;quickMenu.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{quickMenu.hidden=true;switch(b.dataset.quick){case'undo':undo();break;case'redo':redo();break;case'paste':pasteFromClipboard();break;case'clear':clearCanvas();break;case'canvas':setTab('canvas');set3DView(false);break;case'controls':setInteractionControls(!showInteractionControls);break;case'reset':reset3DView();break;case'screenshot':takeWorkspaceScreenshot();break}});document.addEventListener('pointerdown',e=>{if(!quickMenu.contains(e.target)&&e.target!==moreButton)quickMenu.hidden=true});

document.addEventListener('keydown',e=>{if(view3d&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){if(e.key.toLowerCase()==='w'&&transformControls3d){transformControls3d.setMode('translate');e.preventDefault()}if(e.key.toLowerCase()==='e'&&transformControls3d){transformControls3d.setMode('rotate');e.preventDefault()}if(e.key.toLowerCase()==='r'&&transformControls3d){transformControls3d.setMode('scale');e.preventDefault()}}if(selectionObj&&e.key==='Enter'){commitSelection();toast('Selection placed')}if(selectionObj&&e.key==='Escape'){commitSelection();toast('Selection closed')}});
